import{_ as r,C as l,o as n,c as s,j as i,E as d,a as o,a2 as e}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"n":5,"bob":"III-bob · Kompyuter tarmoqlari","lessons":[{"g":13,"title":"Matn filtralari va muntazam ifodalar: grep, sed, awk va xargs amaliyoti","lead":"Server logi millionlab qator. Ko'z bilan o'qib bo'lmaydi, lekin grep, sed va awk bilan bir soniyada kerakli narsani topamiz.","link":"/mentor/10-sinf-devops/hafta-05/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-1-test.html"},{"g":14,"title":"Linux jarayonlari va rejalashtirish: cron, crontab, at va tizim monitoringi (htop, iotop)","lead":"Server har kecha o'zi zaxira oladi, uxlayotganingizda ham. Buni cron qiladi. Bugun vazifalarni vaqtga bog'lashni va tizim yuklamasini kuzatishni o'rganamiz.","link":"/mentor/10-sinf-devops/hafta-05/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-2-test.html"},{"g":15,"title":"Linux xavfsizligi va foydalanuvchilar: useradd, usermod, sudoers, SSH kalitlar bilan xavfsiz ulanish","lead":"Serverga uchta dasturchi kirishi kerak. Hamma bitta parol bilan kirsa, kim nima qilganini bilib bo'lmaydi. Bugun hisoblar, huquqlar va SSH kalitlarni o'rganamiz.","link":"/mentor/10-sinf-devops/hafta-05/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-05/index.md","filePath":"mentor/10-sinf-devops/hafta-05/index.md"}`),c={name:"mentor/10-sinf-devops/hafta-05/index.md"},h={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},v={id:"baholash-mezoni",tabindex:"-1"};function m(f,a,b,y,k,q){const t=l("Icon");return n(),s("div",null,[i("div",h,[i("h2",g,[d(t,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=e('<p>5-haftada matn bilan ishlash vositalari (<code>grep</code>, <code>sed</code>, <code>awk</code>, <code>xargs</code>), jarayonlar va rejalashtirish (<code>cron</code>, <code>at</code>, <code>htop</code>, <code>iotop</code>) hamda foydalanuvchilar va SSH kalitlar o&#39;rganildi. Quyidagi topshiriqlar shu ko&#39;nikmalarni mustahkamlaydi.</p><hr><h2 id="_13-dars-vazifasi-grep-sed-awk-va-xargs" tabindex="-1">13-dars vazifasi: grep, sed, awk va xargs <a class="header-anchor" href="#_13-dars-vazifasi-grep-sed-awk-va-xargs" aria-label="Permalink to &quot;13-dars vazifasi: grep, sed, awk va xargs&quot;">​</a></h2><ol><li><code>app.log</code> ga kamida 10 qator yozing (INFO, WARN, ERROR aralash).</li><li><code>grep -c</code> bilan har daraja sonini toping.</li><li><code>awk</code> bilan faqat ERROR qatorlaridagi foydalanuvchi nomlarini ajrating.</li><li><code>sed</code> bilan ERROR ni XATO ga almashtiring (natijani yangi faylga yo&#39;naltiring).</li><li><code>tahlil.sh</code> skriptiga hammasini yig&#39;ib, natijani daftaringizga yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_14-dars-vazifasi-cron-at-va-monitoring" tabindex="-1">14-dars vazifasi: cron, at va monitoring <a class="header-anchor" href="#_14-dars-vazifasi-cron-at-va-monitoring" aria-label="Permalink to &quot;14-dars vazifasi: cron, at va monitoring&quot;">​</a></h2><ol><li><code>tekshir.sh</code> yozing: sana va bo&#39;sh disk joyini (<code>df -h /</code>) <code>~/tekshir.log</code> ga qo&#39;shib yozsin.</li><li>Skriptni <code>chmod +x</code> qiling va to&#39;liq yo&#39;l bilan har 5 daqiqada ishlaydigan crontab qatorini qo&#39;shing.</li><li><code>crontab -l</code> natijasini va <code>tekshir.log</code> ning bir nechta qatorini daftaringizga yozing, so&#39;ng vazifani o&#39;chiring.</li><li><code>at now + 3 minutes</code> bilan <code>salom.txt</code> yarating; <code>atq</code> ni tekshiring.</li><li><code>htop</code> va <code>iotop</code> ekranini tavsiflang: eng ko&#39;p CPU va disk ishlatgan 3 jarayon nomini yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_15-dars-vazifasi-foydalanuvchilar-sudoers-va-ssh" tabindex="-1">15-dars vazifasi: Foydalanuvchilar, sudoers va SSH <a class="header-anchor" href="#_15-dars-vazifasi-foydalanuvchilar-sudoers-va-ssh" aria-label="Permalink to &quot;15-dars vazifasi: Foydalanuvchilar, sudoers va SSH&quot;">​</a></h2><ol><li>Virtual mashinada <code>dasturchi1</code> hisobini yarating (<code>useradd -m -s /bin/bash</code>) va parol bering.</li><li><code>dasturchi1</code> ni <code>sudo</code> va <code>docker</code> guruhlariga <code>-aG</code> bilan qo&#39;shing; <code>id</code> natijasini yozing.</li><li><code>ssh-keygen -t ed25519</code> bilan kalit yarating; ochiq va shaxsiy kalit fayllarini tavsiflang.</li><li><code>~/.ssh</code> va kalit fayllariga to&#39;g&#39;ri ruxsatlarni bering (<code>chmod 700</code>, <code>chmod 600</code>).</li><li><code>sshd_config</code> da xavfsizlik sozlamalari (parolni o&#39;chirish, root kirishini taqiqlash) ni sinfdagi namunaviy serverda ko&#39;rsating yoki daftarga yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li><strong>Tekshirish mezonlari:</strong><ol><li><code>grep</code>, <code>sed</code>, <code>awk</code> buyruqlari to&#39;g&#39;ri flaglar bilan ishlatilgan, natija <code>app.log</code> bo&#39;yicha to&#39;g&#39;ri.</li><li>Cron qatori 5 maydon bilan to&#39;g&#39;ri yozilgan, skript to&#39;liq yo&#39;l bilan chaqirilgan va bajariladigan (<code>chmod +x</code>).</li><li><code>at</code> vazifasi navbatda ko&#39;rinadi (<code>atq</code>), jarayonni to&#39;xtatish <code>kill</code> bilan bajarilgan.</li><li>Foydalanuvchi <code>useradd -m</code> bilan yaratilgan, guruhga <code>-aG</code> bilan qo&#39;shilgan.</li><li>SSH kalit <code>ed25519</code>, ruxsatlar 700/600, shaxsiy kalit hech kimga uzatilmagan.</li></ol></li><li><strong>Tez-tez uchraydigan xatolar:</strong><ul><li>Naqshni tirnoqqa olmaslik; <code>grep</code> ning o&#39;zini jarayon sifatida topishi.</li><li>Cron da <code>* * * * *</code> ni sinovdan keyin o&#39;chirmaslik.</li><li><code>usermod -G</code> ni <code>-a</code> siz yozish.</li><li>Shaxsiy kalitni (<code>id_ed25519</code>) ulashish yoki <code>.pub</code> bilan adashtirish.</li></ul></li></ul>',13))]),i("div",u,[i("h2",v,[d(t,{name:"list-checks"}),a[3]||(a[3]=o(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=e('<p><strong>Mavzular:</strong></p><ol><li>Matn filtralari va muntazam ifodalar: <code>grep</code>, regex, <code>sed</code>, <code>awk</code>, <code>xargs</code></li><li>Linux jarayonlari va rejalashtirish: <code>ps</code>, <code>top</code>, <code>htop</code>, <code>iotop</code>, <code>cron</code>, <code>crontab</code>, <code>at</code></li><li>Linux xavfsizligi va foydalanuvchilar: <code>useradd</code>, <code>usermod</code>, <code>sudoers</code>, SSH kalitlar</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Matn filtralari</strong></td><td><code>grep</code> flaglari, regex naqshlari, <code>sed</code> almashtirish, <code>awk</code> ustunlari, <code>xargs</code> zanjirlari</td><td>35 ball</td></tr><tr><td><strong>Jarayonlar va rejalashtirish</strong></td><td><code>ps</code>/<code>top</code>/<code>htop</code>/<code>iotop</code>, <code>kill</code>, crontab 5 maydon, <code>at</code></td><td>35 ball</td></tr><tr><td><strong>Foydalanuvchilar va SSH</strong></td><td><code>useradd</code>/<code>usermod -aG</code>, <code>visudo</code>, sudo huquqi, SSH kalit va ruxsatlar</td><td>30 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Matn filtralari (35)</th><th>Jarayonlar/cron (35)</th><th>Foydalanuvchilar/SSH (30)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> naqshni tirnoqsiz yozish, <code>awk</code> ustun raqamini adashtirish, cron da daqiqa va soat o&#39;rnini almashtirish, nisbiy yo&#39;l ishlatish, <code>usermod -aG</code> da <code>-a</code> ni unutish, <code>~/.ssh</code> ruxsatlari.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> loglarni tahlil qiluvchi <code>loganaliz.sh</code> (grep, awk, sort, uniq birga) yoki cron bilan avtomatik disk monitoringi.</li><li><strong>Xavfsizlik:</strong> <code>userdel</code>, <code>kill -9</code>, <code>sshd_config</code> mashqlari faqat laboratoriya muhitida bajarilganini tekshiring.</li></ul>',11))])])}const x=r(c,[["render",m]]);export{z as __pageData,x as default};
